require_once __DIR__.'/../config/fungsi.php';$cat=$_GET['kategori']??'';$search=trim($_GET['q']??'');$sql='SELECT * FROM kontestan WHERE 1=1';$args=[];
if(in_array($cat,['Kakang','Senduk'],true)){$sql.=' AND kategori=?';$args[]=$cat;}
if($search!==''){$sql.=' AND (nama LIKE ? OR nomor_peserta LIKE ? OR asal_instansi LIKE ?)';array_push($args,"%$search%","%$search%","%$search%");}
$sql.=' ORDER BY kategori, nomor_peserta';$q=$pdo->prepare($sql);$q->execute($args);$rows=$q->fetchAll();$page_title='Daftar Kontestan';require __DIR__.'/../includes/header.php';?>
<div class="d-flex flex-wrap justify-content-between align-items-end gap-3 mb-4"><div><div class="eyebrow">Para finalis</div><h1 class="section-title">Kontestan Kakang & Senduk</h1></div><form class="d-flex gap-2"><input class="form-control" name="q" placeholder="Cari kontestan..." value="<?= e($search) ?>"><select class="form-select" name="kategori"><option value="">Semua kategori</option><option <?= $cat==='Kakang'?'selected':'' ?>>Kakang</option><option <?= $cat==='Senduk'?'selected':'' ?>>Senduk</option></select><button class="btn btn-dark">Cari</button></form></div>
<div class="row g-4"><?php foreach($rows as $k): ?><div class="col-sm-6 col-lg-4"><div class="candidate-card"><img src="<?= e(base_url($k['foto']?:'assets/img/placeholder.svg')) ?>" alt="<?= e($k['nama']) ?>"><div class="card-body"><div class="d-flex justify-content-between mb-3"><span class="candidate-number"><?= e($k['nomor_peserta']) ?></span><span class="badge text-bg-light"><?= e($k['kategori']) ?></span></div><h3 class="h5 fw-bold"><?= e($k['nama']) ?></h3><p class="text-muted small"><?= e($k['asal_instansi']) ?></p><p><?= e(mb_strimwidth($k['deskripsi']??'',0,105,'...')) ?></p><a class="btn btn-outline-dark btn-sm" href="detail-kontestan.php?id=<?= (int)$k['id'] ?>">Lihat Detail</a></div></div></div><?php endforeach; ?><?php if(!$rows): ?><div class="col-12"><div class="panel text-center">Belum ada kontestan yang sesuai.</div></div><?php endif; ?></div>
